syntax:
union union_name {
    data_type member1;
    data_type member2;
    // ... more members
};

code_example:
#include <stdio.h>
#include <string.h>
union data {
    int ival;
    float fval;
    char sval[20];
};
int main() {
    union data u;
    u.ival = 10;
    printf("Integer value: %d\n", u.ival);
    u.fval = 3.14f;
    printf("Float value: %f\n", u.fval);
    strcpy(u.sval, "Hello");
    printf("String value: %s\n", u.sval);
    return 0;
}
